	return path, data, hex.EncodeToString(sum[:])
}

func uploadRequest(path, digest string, partSize int64) imageimport.UploadRequest {
	return imageimport.UploadRequest{Namespace: "ns", Bucket: "images", Object: "images/" + digest + ".qcow2", Path: path,
		SHA256: digest, Metadata: map[string]string{"sha256": digest}, PartSize: partSize, Parallelism: 3}
}

// stand-in.
func NewClient(factory *ociclient.Factory, endpoint string) (API, error) {
	return newSDKClient(factory, endpoint)
}

func newSDKClient(factory *ociclient.Factory, endpoint string) (*sdkClient, error) {
	compute, err := factory.Compute()
	if err != nil {
		return nil, err
	}
	objects, err := factory.ObjectStorage()
	if err != nil {
		return nil, err
	}
	work, err := factory.WorkRequests()
	if err != nil {
		return nil, err
	}
	ociclient.PinHost(&compute.BaseClient, endpoint)
	ociclient.PinHost(&objects.BaseClient, endpoint)
	ociclient.PinHost(&work.BaseClient, endpoint)
	return &sdkClient{compute: compute, objects: objects, workRequest: work,
		uploadRetry: ociclient.IdempotentPutRetryPolicy(ociclient.RetryOptions{})}, nil
}

func (c *sdkClient) UploadObject(ctx context.Context, request UploadRequest) error {
	return c.streamUpload(ctx, request)
}

func (c *sdkClient) streamUpload(ctx context.Context, request UploadRequest) error {
	if len(request.SHA256) != sha256.Size*2 {
		return errors.New("upload requires the expected SHA-256")
	}
	if request.PartSize < 1 || request.Parallelism < 1 {
		return errors.New("upload part size and parallelism must be positive")
	}
	file, err := os.Open(request.Path)
	if err != nil {
		return fmt.Errorf("open QCOW2: %w", err)
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return fmt.Errorf("stat QCOW2: %w", err)
	}
	parts := &partReader{file: file, partSize: request.PartSize, expected: info.Size()}
	digest := sha256.New()
	first, release, err := parts.next(ctx)
	if err != nil {
		return err
	}
	if int64(len(first)) < request.PartSize {
		defer release()
		digest.Write(first)
		if err := matches(digest, request.SHA256); err != nil {
			return err
		}
		sum := md5.Sum(first)
		_, err := c.objects.PutObject(ociclient.RequestContext(ctx), objectstorage.PutObjectRequest{NamespaceName: new(request.Namespace),
			BucketName: new(request.Bucket), ObjectName: new(request.Object), ContentLength: new(int64(len(first))),
			PutObjectBody: io.NopCloser(bytes.NewReader(first)), IfNoneMatch: new("*"), OpcMeta: request.Metadata,
			ContentMD5: new(base64.StdEncoding.EncodeToString(sum[:]))})
		if err != nil {
			return fmt.Errorf("upload OCI object: %w", err)
		}
		return nil
	}
	return c.multipartUpload(ctx, request, parts, digest, first, release)
}

// partReader reads the QCOW2 sequentially in parts. Buffers are sized by
// the bytes the file was stated to have left (plus one, so growth is still
// read and fails the digest), never by the part size alone: a small file
// with a huge configured part size does not allocate the part size.
type partReader struct {
	file     io.Reader
	partSize int64
	expected int64
	offset   int64
}

// next reads the next part after reserving its buffer from the process
// budget. release returns the reservation.
func (p *partReader) next(ctx context.Context) ([]byte, func(), error) {
	size := min(p.partSize, max(p.expected-p.offset, 0)+1)
	weight := min(size, uploadBufferBudget)
	if err := uploadBuffers.Acquire(ctx, weight); err != nil {
		return nil, nil, err
	}
	release := sync.OnceFunc(func() { uploadBuffers.Release(weight) })
	buffer := make([]byte, size)
	n, err := io.ReadFull(p.file, buffer)
	if err != nil && !errors.Is(err, io.EOF) && !errors.Is(err, io.ErrUnexpectedEOF) {
		release()
		return nil, nil, fmt.Errorf("read QCOW2: %w", err)
	}
	p.offset += int64(n)
	return buffer[:n], release, nil
}

func matches(digest hash.Hash, want string) error {
	if hex.EncodeToString(digest.Sum(nil)) != want {
		return ErrUploadDigestMismatch
	}
	return nil
}

func (c *sdkClient) multipartUpload(ctx context.Context, request UploadRequest, parts *partReader, digest hash.Hash,
	first []byte, release func(),
) (err error) {
	// Unlike PutObject's OpcMeta header, the multipart body takes the
	// opc-meta- prefix in each key; OCI refuses a bare key.
	metadata := make(map[string]string, len(request.Metadata))
	for name, value := range request.Metadata {
		metadata["opc-meta-"+name] = value
	}
	created, err := c.objects.CreateMultipartUpload(ociclient.RequestContext(ctx), objectstorage.CreateMultipartUploadRequest{
		NamespaceName: new(request.Namespace), BucketName: new(request.Bucket), IfNoneMatch: new("*"),
		CreateMultipartUploadDetails: objectstorage.CreateMultipartUploadDetails{Object: new(request.Object),
			Metadata: metadata}})
	if err != nil {
		release()
		return fmt.Errorf("create OCI multipart upload: %w", err)
	}
	if created.UploadId == nil || *created.UploadId == "" {
		release()
		return errors.New("OCI multipart upload has no upload id")
	}
	uploadID := *created.UploadId
	committed := false
	defer func() {
		if committed {
			return
		}
		// Never leave the uncommitted parts behind, even when ctx ended.
		abortCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), abortTimeout)
		defer cancel()
		if _, abortErr := c.objects.AbortMultipartUpload(ociclient.RequestContext(abortCtx), objectstorage.AbortMultipartUploadRequest{
			NamespaceName: new(request.Namespace), BucketName: new(request.Bucket), ObjectName: new(request.Object),
			UploadId: new(uploadID)}); abortErr != nil {
			err = errors.Join(err, fmt.Errorf("abort OCI multipart upload %s: %w", uploadID, abortErr))
		}
	}()

	group, groupCtx := errgroup.WithContext(ctx)
	group.SetLimit(request.Parallelism)
	// Keep cancellation out of common.Retry's unsynchronized result path
	// (oci-go-sdk v65.126.0/1), but restore it before rate limiting and HTTP
	// dispatch so stalled writes and response headers still get canceled.
	objects := c.objects
	intercept := objects.Interceptor
	objects.Interceptor = func(request *http.Request) error {
		*request = *request.WithContext(groupCtx)
		if err := groupCtx.Err(); err != nil {
			return err
		}
		if intercept != nil {
			return intercept(request)
		}
		return nil
	}
	retry := c.uploadRetry
	retry.ShouldRetryOperation = func(response common.OCIOperationResponse) bool {
		if groupCtx.Err() != nil || !c.uploadRetry.ShouldRetryOperation(response) {
			return false
		}
		// Wait here instead of common.Retry's unconditional backoff timer.
		timer := time.NewTimer(c.uploadRetry.NextDuration(response))
		defer timer.Stop()
		select {
		case <-groupCtx.Done():
			return false
		case <-timer.C:
			return groupCtx.Err() == nil
		}
	}
	retry.NextDuration = func(common.OCIOperationResponse) time.Duration { return 0 }
	var mu sync.Mutex
	etags := map[int]string{}
	var md5s [][]byte
	part, buffer := 0, first
	for len(buffer) > 0 {
		part++
		if part > maxUploadParts {
			release()
			return errors.Join(group.Wait(),
				fmt.Errorf("QCOW2 needs more than %d parts; raise the part size", maxUploadParts))
		}
		digest.Write(buffer)
		sum := md5.Sum(buffer)
		md5s = append(md5s, sum[:])
		number, body, done := part, buffer, release
		group.Go(func() error {
			defer done()
			response, err := objects.UploadPart(context.WithoutCancel(groupCtx), objectstorage.UploadPartRequest{
				NamespaceName: new(request.Namespace), BucketName: new(request.Bucket), ObjectName: new(request.Object),
				UploadId: new(uploadID), UploadPartNum: new(number), ContentLength: new(int64(len(body))),
				UploadPartBody: io.NopCloser(bytes.NewReader(body)),
				ContentMD5:     new(base64.StdEncoding.EncodeToString(sum[:])),
				// Replaying a part of the same bytes and number is idempotent.
				RequestMetadata: common.RequestMetadata{RetryPolicy: &retry}})
			if err != nil {
				if cancelErr := groupCtx.Err(); cancelErr != nil {
					err = cancelErr
				}
				return fmt.Errorf("upload OCI part %d: %w", number, err)
			}
			if response.ETag == nil || *response.ETag == "" {
				return fmt.Errorf("OCI part %d has no ETag", number)
			}
			mu.Lock()
			etags[number] = *response.ETag
			mu.Unlock()
			return nil
		})
		if int64(len(buffer)) < request.PartSize {
			break
		}
		if buffer, release, err = parts.next(groupCtx); err != nil {
			// A failed part cancels groupCtx; report its cause, not the
			// cancellation it caused here.
			if workerErr := group.Wait(); workerErr != nil {
				return workerErr
			}
			return err
		}
		if len(buffer) == 0 {
			release()
		}
	}
	if err := group.Wait(); err != nil {
		return err
	}
	// Every byte sent has been hashed in order; commit only an exact match.
	if err := matches(digest, request.SHA256); err != nil {
		return err
	}
	commit := make([]objectstorage.CommitMultipartUploadPartDetails, 0, part)
	for number := 1; number <= part; number++ {
		commit = append(commit, objectstorage.CommitMultipartUploadPartDetails{PartNum: new(number), Etag: new(etags[number])})
	}
	response, err := c.objects.CommitMultipartUpload(ociclient.RequestContext(ctx), objectstorage.CommitMultipartUploadRequest{
		NamespaceName: new(request.Namespace), BucketName: new(request.Bucket), ObjectName: new(request.Object),
		UploadId: new(uploadID), IfNoneMatch: new("*"),
		CommitMultipartUploadDetails: objectstorage.CommitMultipartUploadDetails{PartsToCommit: commit}})
	if err != nil {
		return fmt.Errorf("commit OCI multipart upload: %w", err)
	}
	committed = true
	if want := multipartMD5(md5s); response.OpcMultipartMd5 == nil || *response.OpcMultipartMd5 != want {
		// The stored object is not the verified bytes; remove exactly that
		// object version so its sha256 metadata can never vouch for it.
		mismatch := fmt.Errorf("committed OCI object multipart MD5 differs from the bytes sent (want %s)", want)
		if response.ETag == nil || *response.ETag == "" {
			// Without the commit's ETag a delete could remove a different
			// object written since; leave it for an operator instead.
			return fmt.Errorf("%w; the commit returned no ETag, so the object was not deleted", mismatch)
		}
		deleteCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), abortTimeout)
		defer cancel()
		if _, deleteErr := c.objects.DeleteObject(ociclient.RequestContext(deleteCtx), objectstorage.DeleteObjectRequest{
			NamespaceName: new(request.Namespace), BucketName: new(request.Bucket), ObjectName: new(request.Object),
			IfMatch: response.ETag}); deleteErr != nil {
			return errors.Join(mismatch, fmt.Errorf("delete mismatched OCI object: %w", deleteErr))
		}
		return mismatch
	}
	return nil
}

// multipartMD5 is Object Storage's checksum of a multipart object: the MD5
// of the concatenated part MD5s, base64, with the part count.
func multipartMD5(parts [][]byte) string {
	all := md5.New()
	for _, sum := range parts {
		all.Write(sum)
	}
	return base64.StdEncoding.EncodeToString(all.Sum(nil)) + "-" + strconv.Itoa(len(parts))
}

func Start(t testing.TB, imageID string) *Server {
	t.Helper()
	s := &Server{imageID: imageID, created: time.Now().UTC().Truncate(time.Second), objects: map[string]object{},
		work: map[string]int{}, workIDs: map[string]string{}, shapes: map[string][]shape{},
		uploads: map[string]*upload{}}
	server := httptest.NewServer(s.handler())
	t.Cleanup(server.Close)
	s.URL = server.URL
	return s
}

// Requests returns every request served so far as "METHOD /path".
func (s *Server) Requests() []string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return slices.Clone(s.requests)
}

// Count returns how many served requests start with prefix.
func (s *Server) Count(prefix string) int {
	count := 0
	for _, request := range s.Requests() {
		if strings.HasPrefix(request, prefix) {
			count++
		}
	}
	return count
}

// Object returns a stored object's bytes and user metadata.
func (s *Server) Object(namespace, bucket, name string) ([]byte, map[string]string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	stored, ok := s.objects[namespace+"/"+bucket+"/"+name]
	return stored.data, stored.metadata, ok
}

func reply(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("opc-request-id", "standin")
	w.WriteHeader(status)
	if value != nil {
		_ = json.MarshalWrite(w, value)
	}
}

func refuse(w http.ResponseWriter, status int, code, message string) {
	reply(w, status, map[string]string{"code": code, "message": message})
}

func (s *Server) handler() http.Handler {
	mux := http.NewServeMux()
	const core = "/20160918"
	mux.HandleFunc("HEAD /n/{namespace}/b/{bucket}/o/{object...}", s.headObject)
	mux.HandleFunc("PUT /n/{namespace}/b/{bucket}/o/{object...}", s.putObject)
	s.routeMultipart(mux)
	mux.HandleFunc("GET "+core+"/images", s.listImages)
	mux.HandleFunc("POST "+core+"/images", s.createImage)
	mux.HandleFunc("GET "+core+"/images/{id}", s.getImage)
	mux.HandleFunc("GET "+core+"/workRequests/{id}", s.getWorkRequest)
	mux.HandleFunc("GET "+core+"/computeImageCapabilitySchemas", s.listSchemas)
	mux.HandleFunc("POST "+core+"/computeImageCapabilitySchemas", s.createSchema)
	mux.HandleFunc("GET "+core+"/computeImageCapabilitySchemas/{id}", s.getSchema)
	mux.HandleFunc("GET "+core+"/computeGlobalImageCapabilitySchemas", func(w http.ResponseWriter, r *http.Request) {
		// The first page is empty and points at the next one, so the
		// client must follow pagination to find the schema.
		if r.URL.Query().Get("page") == "" {
			w.Header().Set("opc-next-page", "global-schemas-2")
			reply(w, http.StatusOK, []map[string]string{})
			return
		}
		reply(w, http.StatusOK, []map[string]string{{"id": "ocid1.computeglobalimgcapschema.standin", "currentVersionName": "standin-v1"}})
	})
	mux.HandleFunc("GET "+core+"/images/{id}/shapes", s.listShapes)
	mux.HandleFunc("PUT "+core+"/images/{id}/shapes/{shape}", s.addShape)
	mux.HandleFunc("DELETE "+core+"/images/{id}/shapes/{shape}", s.removeShape)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Every SDK request is signed; an unsigned request is not the client
		// under test.
		if !strings.HasPrefix(r.Header.Get("Authorization"), "Signature ") {
			refuse(w, http.StatusUnauthorized, "NotAuthenticated", "unsigned request")
			return
		}
		s.mu.Lock()
		s.requests = append(s.requests, r.Method+" "+r.URL.Path)
		s.mu.Unlock()
		mux.ServeHTTP(w, r)
	})
}

func objectKey(r *http.Request) string {
	return r.PathValue("namespace") + "/" + r.PathValue("bucket") + "/" + r.PathValue("object")
}

func (s *Server) headObject(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	stored, ok := s.objects[objectKey(r)]
	s.mu.Unlock()
	if !ok {
		w.WriteHeader(http.StatusNotFound)
		return
	}
	for key, value := range stored.metadata {
		w.Header().Set("opc-meta-"+key, value)
	}
	w.Header().Set("Content-Length", fmt.Sprint(len(stored.data)))
	w.Header().Set("ETag", "standin")
	w.WriteHeader(http.StatusOK)
}

func (s *Server) putObject(w http.ResponseWriter, r *http.Request) {
	data, err := io.ReadAll(r.Body)
	if err != nil {
		refuse(w, http.StatusBadRequest, "InvalidParameter", err.Error())
		return
	}
	if want := r.Header.Get("Content-MD5"); want != "" && want != contentMD5(data) {
		refuse(w, http.StatusBadRequest, "InvalidContentMD5", "object MD5 mismatch")
		return
	}
	metadata := map[string]string{}
	for key, values := range r.Header {
		if name, ok := strings.CutPrefix(strings.ToLower(key), "opc-meta-"); ok && len(values) > 0 {
			metadata[name] = values[0]
		}
	}
	key := objectKey(r)
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.objects[key]; exists && r.Header.Get("If-None-Match") == "*" {
		refuse(w, http.StatusPreconditionFailed, "IfNoneMatchFailed", "object exists")
		return
	}
	s.objects[key] = object{data: data, metadata: metadata}
	w.Header().Set("ETag", "standin")
	w.WriteHeader(http.StatusOK)
}

func Client(endpoint, region string) (imageimport.API, error) {
	key, err := signingKey()
	if err != nil {
		return nil, err
	}
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..standin", "ocid1.user.oc1..standin", region,
		"00:00:00:00:00:00:00:00:00:00:00:00:00:00:00:00", key, nil)
	factory, err := ociclient.New(provider, ociclient.Options{Region: region,
		Retry: ociclient.RetryOptions{MaxAttempts: 1}})
	if err != nil {
		return nil, err
	}
	return imageimport.NewClient(factory, endpoint)
}

func (s *Server) Multipart() (open, aborted int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return len(s.uploads), s.aborted
}

// SetPartHook runs before every stored part; tests use it to change the
// source file mid-upload.
func (s *Server) SetPartHook(hook func(part int)) {
	s.mu.Lock()
	s.partHook = hook
	s.mu.Unlock()
}

// SetPartFailure makes every later part upload fail with status (0 clears).
func (s *Server) SetPartFailure(status int) {
	s.mu.Lock()
	s.partFailure = status
	s.mu.Unlock()
}

func (s *Server) routeMultipart(mux *http.ServeMux) {
	mux.HandleFunc("POST /n/{namespace}/b/{bucket}/u", s.createUpload)
	mux.HandleFunc("PUT /n/{namespace}/b/{bucket}/u/{object...}", s.uploadPart)
	mux.HandleFunc("POST /n/{namespace}/b/{bucket}/u/{object...}", s.commitUpload)
	mux.HandleFunc("DELETE /n/{namespace}/b/{bucket}/u/{object...}", s.abortUpload)
}

func contentMD5(data []byte) string {
	sum := md5.Sum(data)
	return base64.StdEncoding.EncodeToString(sum[:])
}

func (s *Server) createUpload(w http.ResponseWriter, r *http.Request) {
	var details struct {
		Object   string            `json:"object"`
		Metadata map[string]string `json:"metadata"`
	}
	if err := json.UnmarshalRead(r.Body, &details); err != nil || details.Object == "" {
		refuse(w, http.StatusBadRequest, "InvalidParameter", "bad multipart upload details")
		return
	}
	// Like OCI, the body's metadata keys carry the opc-meta- prefix that a
	// PutObject header gets from the SDK; the stored object keeps the bare key.
	metadata := map[string]string{}
	for name, value := range details.Metadata {
		bare, ok := strings.CutPrefix(strings.ToLower(name), "opc-meta-")
		if !ok {
			refuse(w, http.StatusBadRequest, "InvalidMetadata", fmt.Sprintf("The metadata key %q is invalid", name))
			return
		}
		metadata[bare] = value
	}
	key := r.PathValue("namespace") + "/" + r.PathValue("bucket") + "/" + details.Object
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, exists := s.objects[key]; exists && r.Header.Get("If-None-Match") == "*" {
		refuse(w, http.StatusPreconditionFailed, "IfNoneMatchFailed", "object exists")
		return
	}
	s.uploadSeq++
	id := fmt.Sprintf("upload-%d", s.uploadSeq)
	s.uploads[id] = &upload{key: key, metadata: metadata, parts: map[int][]byte{}}
	reply(w, http.StatusOK, map[string]string{"namespace": r.PathValue("namespace"), "bucket": r.PathValue("bucket"),
		"object": details.Object, "uploadId": id, "timeCreated": s.created.Format("2006-01-02T15:04:05Z")})
}

func (s *Server) openUpload(w http.ResponseWriter, r *http.Request) *upload {
	stored, ok := s.uploads[r.URL.Query().Get("uploadId")]
	if !ok || stored.key != objectKey(r) {
		refuse(w, http.StatusNotFound, "NoSuchUpload", "upload does not exist")
		return nil
	}
	return stored
}

func (s *Server) uploadPart(w http.ResponseWriter, r *http.Request) {
	data, err := io.ReadAll(r.Body)
	if err != nil {
		refuse(w, http.StatusBadRequest, "InvalidParameter", err.Error())
		return
	}
	number, err := strconv.Atoi(r.URL.Query().Get("uploadPartNum"))
	if err != nil || number < 1 || number > 10000 {
		refuse(w, http.StatusBadRequest, "InvalidParameter", "bad part number")
		return
	}
	if want := r.Header.Get("Content-MD5"); want != "" && want != contentMD5(data) {
		refuse(w, http.StatusBadRequest, "InvalidContentMD5", "part MD5 mismatch")
		return
	}
	s.mu.Lock()
	if s.partFailure != 0 {
		s.mu.Unlock()
		refuse(w, s.partFailure, "NotAuthorizedOrNotFound", "part refused")
		return
	}
	hook := s.partHook
	stored := s.openUpload(w, r)
	if stored != nil {
		stored.parts[number] = data
	}
	s.mu.Unlock()
	if stored == nil {
		return
	}
	if hook != nil {
		hook(number)
	}
	w.Header().Set("ETag", fmt.Sprintf("part-%d-%s", number, contentMD5(data)))
	w.Header().Set("opc-content-md5", contentMD5(data))
	w.WriteHeader(http.StatusOK)
}

func (s *Server) commitUpload(w http.ResponseWriter, r *http.Request) {
	var details struct {
		PartsToCommit []struct {
			PartNum int    `json:"partNum"`
			Etag    string `json:"etag"`
		} `json:"partsToCommit"`
	}
	if err := json.UnmarshalRead(r.Body, &details); err != nil || len(details.PartsToCommit) == 0 {
		refuse(w, http.StatusBadRequest, "InvalidParameter", "bad commit details")
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	stored := s.openUpload(w, r)
	if stored == nil {
		return
	}
	if _, exists := s.objects[stored.key]; exists && r.Header.Get("If-None-Match") == "*" {
		refuse(w, http.StatusPreconditionFailed, "IfNoneMatchFailed", "object exists")
		return
	}
	slices.SortFunc(details.PartsToCommit, func(a, b struct {
		PartNum int    `json:"partNum"`
		Etag    string `json:"etag"`
	}) int {
		return a.PartNum - b.PartNum
	})
	var data, md5s []byte
	for _, part := range details.PartsToCommit {
		body, ok := stored.parts[part.PartNum]
		if !ok || part.Etag != fmt.Sprintf("part-%d-%s", part.PartNum, contentMD5(body)) {
			refuse(w, http.StatusBadRequest, "InvalidPart", "part etag mismatch")
			return
		}
		data = append(data, body...)
		sum := md5.Sum(body)
		md5s = append(md5s, sum[:]...)
	}
	s.objects[stored.key] = object{data: data, metadata: stored.metadata}
	delete(s.uploads, r.URL.Query().Get("uploadId"))
	all := md5.Sum(md5s)
	w.Header().Set("opc-multipart-md5", base64.StdEncoding.EncodeToString(all[:])+"-"+strconv.Itoa(len(details.PartsToCommit)))
	w.Header().Set("ETag", "standin")
	w.WriteHeader(http.StatusOK)
}

func (s *Server) abortUpload(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.openUpload(w, r) == nil {
		return
	}
	delete(s.uploads, r.URL.Query().Get("uploadId"))
	s.aborted++
	w.WriteHeader(http.StatusNoContent)
}

