func New(provider common.ConfigurationProvider, options Options) (*Factory, error) {
	if provider == nil {
		return nil, errors.New("OCI client factory requires a configuration provider")
	}
	if !catalog.IsOCIRegion(options.Region) {
		return nil, fmt.Errorf("OCI client factory region %q is not in the region catalog", options.Region)
	}
	limits := make(map[Service]Limit, len(DefaultLimits))
	for service, limit := range DefaultLimits {
		limits[service] = limit
	}
	for service, limit := range options.Limits {
		if limit.PerSecond <= 0 || limit.Burst < 1 {
			return nil, fmt.Errorf("OCI client limit for %s must be positive", service)
		}
		limits[service] = limit
	}
	return &Factory{provider: provider, region: options.Region, limits: limits,
		policy: RetryPolicy(options.Retry), limiters: map[Service]*rate.Limiter{}}, nil
}

// Limiter returns the shared token bucket for service.
func (f *Factory) Limiter(service Service) *rate.Limiter {
	f.mu.Lock()
	defer f.mu.Unlock()
	if limiter := f.limiters[service]; limiter != nil {
		return limiter
	}
	limit, ok := f.limits[service]
	if !ok {
		limit = defaultLimit
	}
	limiter := rate.NewLimiter(rate.Limit(limit.PerSecond), limit.Burst)
	f.limiters[service] = limiter
	return limiter
}

// Configure installs the shared limiter and retry policy on an SDK client and
// pins it to the factory region. An existing interceptor still runs, after the
// limiter admits the request. Each retry attempt passes through the limiter.
func (f *Factory) Configure(client *common.BaseClient, service Service) {
	limiter := f.Limiter(service)
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		ctx := request.Context()
		if ctx == nil {
			ctx = context.Background()
		}
		if err := limiter.Wait(ctx); err != nil {
			return fmt.Errorf("OCI %s rate limiter: %w", service, err)
		}
		if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
			if guard, ok := ctx.Value(authorityKey{}).(func(context.Context) error); ok {
				if err := guard(ctx); err != nil {
					return fmt.Errorf("OCI %s write authority: %w", service, err)
				}
			}
		}
		if previous != nil {
			return previous(request)
		}
		return nil
	}
	policy := f.policy
	// Set only the retry policy: replacing the whole configuration would drop
	// a circuit breaker the SDK installed from OCI_SDK_DEFAULT_CIRCUITBREAKER_ENABLED
	// or its global setting.
	client.Configuration.RetryPolicy = &policy
	ConfigureReadCancellation(client)
}

// PinHost replaces a client's endpoint with an exact canonical endpoint. It is
// used by callers whose signed configuration names the endpoint.
func PinHost(client *common.BaseClient, endpoint string) {
	if endpoint = strings.TrimSuffix(endpoint, "/"); endpoint != "" {
		client.Host = endpoint
	}
}

// Compute returns a rate-limited Compute client.
func (f *Factory) Compute() (core.ComputeClient, error) {
	client, err := core.NewComputeClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI Compute client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceCompute)
	return client, nil
}

func (f *Factory) ObjectStorage() (objectstorage.ObjectStorageClient, error) {
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(f.provider)
	if err != nil {
		return client, fmt.Errorf("create OCI Object Storage client: %w", err)
	}
	client.SetRegion(f.region)
	f.Configure(&client.BaseClient, ServiceObjectStorage)
	client.HTTPClient = Instrument(client.HTTPClient, string(ServiceObjectStorage))
	return client, nil
}

// RequestContext keeps the SDK retry goroutine joined while the original context
// cancels the HTTP request and backoff. Use with ConfigureRequestCancellation.
func RequestContext(ctx context.Context) context.Context {
	if originalReadContext(ctx) != nil && ctx.Done() == nil {
		return ctx
	}
	return context.WithValue(context.WithoutCancel(ctx), readContextKey{}, ctx)
}

// ReadContext is RequestContext for existing read callers.
func ReadContext(ctx context.Context) context.Context { return RequestContext(ctx) }

type readContextKey struct{}

func originalReadContext(ctx context.Context) context.Context {
	original, _ := ctx.Value(readContextKey{}).(context.Context)
	return original
}

// ConfigureReadCancellation is retained for existing read callers.
func ConfigureReadCancellation(client *common.BaseClient) { ConfigureRequestCancellation(client) }

// ConfigureRequestCancellation must run after other interceptors are installed.
// It avoids the SDK Retry response race while preserving wire cancellation.
func ConfigureRequestCancellation(client *common.BaseClient) {
	if readCancellationConfigured(client.HTTPClient) {
		return
	}
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		if original := originalReadContext(request.Context()); original != nil {
			*request = *request.WithContext(context.WithValue(original, readContextKey{}, original))
		}
		if previous != nil {
			return previous(request)
		}
		return request.Context().Err()
	}
	client.HTTPClient = readDispatcher{next: client.HTTPClient}
}

func readCancellationConfigured(dispatcher common.HTTPRequestDispatcher) bool {
	switch dispatcher := dispatcher.(type) {
	case readDispatcher:
		return true
	case *instrumentedDispatcher:
		return readCancellationConfigured(dispatcher.next)
	default:
		return false
	}
}

type readDispatcher struct{ next common.HTTPRequestDispatcher }

type readTransportError struct {
	err error
	ctx context.Context
}

func (e *readTransportError) Error() string { return e.err.Error() }
func (e *readTransportError) Unwrap() error { return e.err }

func (d readDispatcher) Do(request *http.Request) (*http.Response, error) {
	var finish func(*http.Response, error, bool) error
	if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
		deadline := new(admissionDeadline)
		*request = *request.WithContext(context.WithValue(request.Context(), admissionDeadlineKey{}, deadline))
		if begin, ok := request.Context().Value(wireAttemptKey{}).(func(*http.Request) (func(*http.Response, error, bool) error, error)); ok {
			if begin == nil {
				return nil, errors.New("OCI wire attempt journal is unavailable")
			}
			var err error
			finish, err = begin(request)
			if err != nil {
				return nil, fmt.Errorf("OCI wire attempt checkpoint: %w", err)
			}
			if finish == nil {
				return nil, errors.New("OCI wire attempt journal lacks outcome recorder")
			}
		}
		deny := func(err error) (*http.Response, error) {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, err
		}
		if finish != nil {
			if err := request.Context().Err(); err != nil {
				return deny(err)
			}
			// The durable begin may block; refresh the claim after that write.
			if guard, ok := request.Context().Value(authorityKey{}).(func(context.Context) error); ok {
				if guard == nil {
					return deny(errors.New("OCI wire authority is unavailable"))
				}
				if err := guard(request.Context()); err != nil {
					return deny(fmt.Errorf("OCI wire authority: %w", err))
				}
			}
		}
		if acquire, ok := request.Context().Value(admissionKey{}).(func(context.Context) (func(), error)); ok {
			if acquire == nil {
				return deny(errors.New("OCI write admission is unavailable"))
			}
			release, err := acquire(request.Context())
			if err != nil {
				return deny(fmt.Errorf("OCI write admission: %w", err))
			}
			if release == nil {
				return deny(errors.New("OCI write admission did not fence current authority"))
			}
			defer release()
		}
		if err := request.Context().Err(); err != nil {
			return deny(err)
		}
		if !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
			return deny(errors.New("OCI current admission facts expired before dispatch"))
		}
	}
	if guard, ok := request.Context().Value(requestGuardKey{}).(func(context.Context) error); ok {
		var err error
		if guard == nil {
			err = errors.New("OCI request session is unavailable")
		} else {
			// Authorization may itself read OCI; those reads must not recurse
			// into the guard they are currently establishing.
			err = guard(context.WithValue(request.Context(), requestGuardKey{}, struct{}{}))
		}
		if err != nil {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, &readTransportError{err: err, ctx: request.Context()}
		}
	}
	// The final source guard may wait past a shorter retained admission cap.
	// Recheck it after that wait, immediately before the actual dispatch.
	finalErr := request.Context().Err()
	if deadline, ok := request.Context().Value(admissionDeadlineKey{}).(*admissionDeadline); ok && !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
		finalErr = errors.Join(finalErr, errors.New("OCI original admission deadline expired during final source guard"))
	}
	if finalErr != nil {
		if finish != nil {
			finalErr = errors.Join(finalErr, finish(nil, finalErr, false))
		}
		return nil, &readTransportError{err: finalErr, ctx: request.Context()}
	}
	response, err := d.next.Do(request)
	if finish != nil {
		if recordErr := finish(response, err, true); recordErr != nil {
			if response != nil && response.Body != nil {
				_ = response.Body.Close()
			}
			err = errors.Join(err, fmt.Errorf("OCI wire outcome remains unknown: %w", recordErr))
		}
	}
	if original := originalReadContext(request.Context()); original != nil && err != nil {
		return response, &readTransportError{err: err, ctx: original}
	}
	return response, err
}

func readOperationContext(response common.OCIOperationResponse) context.Context {
	if failure, ok := errors.AsType[*readTransportError](response.Error); ok {
		return failure.ctx
	}
	if response.Response != nil {
		if raw := response.Response.HTTPResponse(); raw != nil && raw.Request != nil {
			return originalReadContext(raw.Request.Context())
