				seen[id] = true
				images = append(images, Object{"region": region, "id": id, "compartment_id": compartment, "display_name": m["display-name"], "lifecycle_state": m["lifecycle-state"], "billable_size_in_gbs": m["billable-size-in-gbs"]})
			}
